insert into public.state_summaries (state_code, summary, source_name, source_url, verified_at) values
  ('AL', 'The Alabama Division of Construction Management (DCM) adopted the 2021 International Building Code, effective July 1, 2022, and amended it on March 17, 2025 to incorporate portions of the 2024 IBC. DCM jurisdiction covers state-owned property, K-12 and public postsecondary schools, hotels and motels, and movie theaters; authority over the residential code transferred to the Alabama Home Builders Licensure Board on October 1, 2024 (Act 2024-443). Most private construction in Alabama is permitted locally, so always confirm requirements with the city or county building department.', 'Alabama Division of Construction Management — Building Code', 'https://dcm.alabama.gov/bldg_code.aspx', '2026-11-24'),
  ('AK', 'Alaska has no general statewide building code for private construction. The State Fire Marshal (Division of Fire and Life Safety, Department of Public Safety) adopted the 2021 International Building Code, Fire Code, Existing Building Code, Fuel Gas Code and Mechanical Code, effective October 28, 2022 (13 AAC 50), for fire and life safety review of commercial and larger residential buildings; there is no statewide residential code, and small residential buildings are exempt from state plan review. Local governments adopt their own construction codes by ordinance.', '13 AAC 50.020, International Building Code (Cornell LII reproduction of the Alaska Administrative Code)', 'https://www.law.cornell.edu/regulations/alaska/13-AAC-50.020', '2026-11-24'),
  ('AZ', 'Arizona has no statewide building code; building codes are adopted and enforced locally by cities, towns and counties. The one statewide code is the Arizona State Fire Code — the 2024 International Fire Code (A.A.C. R4-36-201), effective April 13, 2026 — enforced by the Office of the State Fire Marshal (Department of Forestry and Fire Management) for state and county buildings and public schools. Always confirm the locally adopted building code edition with the city or county where the project is located.', 'Arizona Dept. of Forestry and Fire Management — State Fire Marshal', 'https://dffm.az.gov/fire-marshal/arizona-state-statute-and-fire-code', '2026-11-24'),
  ('AR', 'Arkansas enforces the Arkansas Fire Prevention Code (AFPC), 2021 edition, based on the 2021 International Fire Code, International Building Code and International Residential Code, effective January 1, 2023. The code is enforced by the Office of the State Fire Marshal in the Arkansas Department of Public Safety. Local jurisdictions may adopt and enforce additional requirements, so confirm the local edition with the city or county building department.', 'Arkansas Dept. of Public Safety — State Fire Marshal', 'https://media.ark.org/dps/ASP-Foreword-Fire-Code-Rules-Clean_10-2024.pdf', '2026-11-24'),
  ('CA', 'California sets building standards statewide in Title 24, the California Building Standards Code, administered by the California Building Standards Commission within the Department of General Services. The current 2025 edition of Title 24 was published July 1, 2025 and took effect January 1, 2026. Local jurisdictions enforce the code and may add local amendments, so confirm any local amendments with the city or county building department.', 'California Building Standards Commission (Dept. of General Services)', 'https://www.dgs.ca.gov/en/BSC/About/History-of-the-California-Building-Standards-Commission', '2026-11-24'),
  ('CO', 'Colorado has no statewide building code for private construction; cities and counties adopt and enforce their own codes. The Division of Fire Prevention and Control (Department of Public Safety) adopts the 2021 IBC, IMC, IECC, IEBC, IRC and IFC (8 CCR 1507-101) for state-overseen property such as public schools and health facilities, and the State Buildings Program adopts the 2021 IBC for state agency construction. Confirm the locally adopted edition with the city or county building department.', 'Colorado Division of Fire Prevention and Control — Adopted Codes', 'https://dfpc.colorado.gov/sections/fire-and-life-safety/fls-adopted-codes', '2026-11-24'),
  ('CT', 'Connecticut enforces the 2022 Connecticut State Building Code, based on the 2021 International Codes, for permit applications filed on or after October 1, 2022. The code is administered by the Office of the State Building Inspector in the Department of Administrative Services and applies statewide. Building permits are issued by local building departments under the state code.', 'Connecticut Office of the State Building Inspector', 'https://portal.ct.gov/das/home/office-of-state-building-inspector/connecticut-state-building-code/regulations', '2026-11-24'),
  ('DE', 'Delaware has no statewide building code; the three counties — New Castle, Kent and Sussex — adopt and enforce their own building, plumbing and electrical codes under 16 Del. C. ch. 76. Statewide rules layer on top: the state energy code moved to the 2024 International Energy Conservation Code in April 2026 (DNREC Secretary''s Order 2026-CCE-0002), and the 2026 Delaware State Fire Prevention Regulations, based on the 2024 NFPA 1 and NFPA 101, took effect January 1, 2026. Confirm the county''s adopted edition before designing a project.', 'Delaware Code, Title 16, Chapter 76', 'https://law.justia.com/codes/delaware/2010/title16/c076.html', '2026-11-24'),
  ('FL', 'Florida enforces the 8th Edition (2023) Florida Building Code, based on the 2021 International Codes, effective December 31, 2023. The code is administered by the Florida Building Commission in the Department of Business and Professional Regulation and applies statewide. Local building departments enforce the code and issue permits; confirm any local amendments with the city or county.', 'Florida Building Commission', 'https://www.floridabuilding.org/fbc/commission/FBC_0124/Energy_TAC/DOE_Code_Certification_Letter-Commercial.pdf', '2026-11-24'),
  ('GA', 'The mandatory construction codes of Georgia are set by the Department of Community Affairs (Board of Community Affairs) and apply statewide. The current state minimum codes (per the DCA page updated March 9, 2026) are the 2024 IBC, IRC, IFC, IPC, IMC and IFGC with Georgia Amendments, the 2023 National Electrical Code and the 2015 International Energy Conservation Code. Local jurisdictions enforce the state minimum codes.', 'Georgia Dept. of Community Affairs — Construction Codes', 'https://dca.georgia.gov/community-assistance/construction-codes/current-state-minimum-codes-construction', '2026-11-24'),
  ('HI', 'The State Building Code of Hawaii is set by the State Building Code Council in the Department of Accounting and General Services. The current Hawaii State Building Code is based on the 2018 International Building Code, effective April 20, 2021, and the council''s current list also includes the 2018 IRC, IECC and IEBC, the 2018 Uniform Plumbing Code and the 2024 NFPA 1 fire code. Building permits are issued by the county building departments.', 'Hawaii State Building Code Council', 'https://ags.hawaii.gov/bcc/building-code-rules/', '2026-11-24'),
  ('ID', 'The building codes of Idaho are set by the Idaho Building Code Board in the Division of Occupational and Professional Licenses. The current adopted codes are the 2018 IBC, IRC, IEBC and IECC with Idaho amendments (identified as the 2020 Edition), the 2023 National Electrical Code and the 2018 International Fire Code, enforced by the State Fire Marshal. Local jurisdictions adopt and enforce the state codes, with permits issued by the city or county building department.', 'Idaho Division of Occupational and Professional Licenses — Adopted Codes', 'https://dopl.idaho.gov/wp-content/uploads/2025/06/2025-Updated-Idaho-Adopted-Codes.pdf', '2026-11-24'),
  ('IL', 'Illinois established a statewide building-code baseline effective January 1, 2025 (Public Act 103-0510), administered by the Capital Development Board: where a local government has no building code, the current or most recent preceding edition of the IBC and IEBC applies, and local codes must be at least as stringent as the state baseline. The state also sets the Illinois Energy Conservation Code, the Illinois Accessibility Code, the Illinois Plumbing Code and the Fire Prevention and Safety Rules (including NFPA 101). Confirm whether the city or county has its own adopted code, since local codes govern where they exist.', 'Illinois Capital Development Board — Building Codes', 'https://cdb.illinois.gov/business/codes/buildingcodesregulations.html', '2026-11-24'),
  ('IN', 'The building code of Indiana is set by the Fire Prevention and Building Safety Commission in the Department of Homeland Security. The 2014 Indiana Building Code (based on the 2012 International Building Code), effective December 1, 2014, is currently in effect, and the 2020 Indiana Residential Code is based on the 2018 International Residential Code. The statewide code covers commercial and residential construction, with permits issued by local building departments.', 'Indiana Fire Prevention and Building Safety Commission', 'http://www.in.gov/dhs/boards-and-commissions/fpbsc-rules', '2026-11-24'),
  ('IA', 'The State Building Code of Iowa, set in Iowa Administrative Code 661, chapter 301 (ARC 9474C, effective September 10, 2025), adopts the 2024 International Building Code by reference. The code is the state building-code standard; confirm with the city or county building department which edition governs a specific project.', 'Iowa Administrative Rules — ARC 9474C (State Building Code)', 'https://rules.iowa.gov/Notice/Details/9474C', '2026-11-24'),
  ('KS', 'Kansas has no mandatory statewide building code; local adoption is the rule under home-rule authority. The State Fire Marshal enforces the Kansas Fire Prevention Code (K.A.R. 22-1-3, which adopts the 2006 IFC and IBC) for state-owned buildings, and adoption of the 2024 IFC has been proposed with no effective date set. Confirm the locally adopted edition with the city or county building department.', 'Kansas State Fire Marshal — Code Listing', 'https://firemarshal.ks.gov/181/Code-Listing', '2026-11-24'),
  ('KY', 'The Department of Housing, Buildings and Construction enforces the 2018 Kentucky Building Code (based on the 2015 IBC) and the 2018 Kentucky Residential Code (based on the 2015 IRC), effective January 1, 2019. The code is a mandatory statewide code (a mini/maxi code): every jurisdiction enforces the same editions, and local governments may not weaken it. Building permits are issued by local building departments under the state code.', 'Kentucky Dept. of Housing, Buildings and Construction', 'https://dhbc.ky.gov/newstatic_info.aspx?static_id=297', '2026-11-24'),
  ('LA', 'Louisiana enforces the Louisiana State Uniform Construction Code: the 2021 IBC, IRC, IPC, IMC, IFGC, IEBC and IECC, plus the 2020 National Electrical Code. The statewide uniform code is enforced locally, so permits are issued by the city or parish building department. Confirm the locally adopted edition and any local amendments with the city or parish building department.', 'Louisiana State Fire Marshal — Plan Review Codes', 'https://www.lasfm.org/plan-review/plan-review-codes-rules-laws/', '2026-11-24'),
  ('ME', 'Maine enforces the Maine Uniform Building and Energy Code (MUBEC): the 2021 IBC, IRC, IEBC, IECC and IMC, effective April 7, 2025. MUBEC applies statewide and is enforced in municipalities with a population of 4,000 or more; the Division of Building Codes and Standards moved to the Maine Office of Community Affairs in September 2025. Building permits are issued by the municipal code enforcement office.', 'Maine Office of Community Affairs — Building Codes', 'https://www1.maine.gov/energy/initiatives/energy-efficiency/building-codes', '2026-11-24'),
  ('MD', 'Maryland enforces the Maryland Building Performance Standards (COMAR 09.12.51, Department of Labor): the 2021 IBC, IRC and IECC, effective May 29, 2023. Every jurisdiction in the state uses the same code edition. Building permits are issued by the county or municipal permitting office.', 'Maryland Dept. of Labor — Building Codes', 'https://labor.maryland.gov/labor/build/buildcodes.shtml', '2026-11-24'),
  ('MA', 'Massachusetts enforces the 10th edition of the Massachusetts State Building Code (780 CMR), effective October 11, 2024, based on the 2021 International Codes as modified for Massachusetts. The code is set by the Board of Building Regulations and Standards and applies statewide. Building permits are issued by local building departments under the state code.', 'Massachusetts Board of Building Regulations and Standards — 780 CMR', 'https://WWW.mass.gov/regulations/780-CMR-tenth-edition-table-of-contents', '2026-11-24'),
  ('MI', 'Michigan enforces the 2021 Michigan Building Code (the 2021 IBC with Michigan amendments), effective April 9, 2025. The 2015 Michigan Residential Code is still the current code for residential construction. Both codes are administered by the Bureau of Construction Codes in the Department of Licensing and Regulatory Affairs (LARA).', 'Michigan Bureau of Construction Codes (LARA)', 'https://www.michigan.gov/lara/bureau-list/bcc/rules-acts/codes/code-books', '2026-11-24'),
  ('MN', 'The Minnesota State Building Code is the uniform statewide minimum standard (Minn. Stat. §326B.121), administered by the Construction Codes and Licensing Division of the Department of Labor and Industry. The published current set of the department is the 2020 Minnesota State Building Codes (based on the 2018 I-Codes); a new code cycle was in the proposal stage in fall 2026 and had not been adopted. Building permits are issued by local building departments under the state code.', 'Minnesota Dept. of Labor and Industry — State Building Code', 'http://dli.mn.gov/business/codes-and-laws/overview-minnesota-state-building-code', '2026-11-24'),
  ('MS', 'Mississippi has no single statewide building code edition. Under Miss. Code §17-2-4, every county and municipality must adopt one of the last three editions of the International Building Code and International Residential Code as the State Uniform Construction Code (in effect since August 1, 2014, Senate Bill 2378), unless it opted out by resolution before November 30, 2014; the five coastal counties must also enforce wind and flood requirements, and the Mississippi Building Codes Council sets the state minimums. Because editions vary by county and city, confirm the adopted code with the local building department.', 'Mississippi Code § 17-2-4 — State Uniform Construction Code', 'https://law.justia.com/codes/mississippi/title-17/chapter-2/section-17-2-4/', '2026-11-24'),
  ('MO', 'Missouri has no statewide building code or fire code. Fire and building codes are adopted at the local level by cities, counties and fire protection districts, as confirmed in the Division of Fire Safety FAQ. Confirm the locally adopted edition with the city, county or fire protection district where the project is located.', 'Missouri Division of Fire Safety — FAQs', 'https://dfs.dps.mo.gov/about/faqs.php', '2026-11-24'),
  ('MT', 'Montana enforces the 2024 IBC, IRC, IEBC, IECC, IMC, IFGC and UPC, plus the 2023 National Electrical Code, effective September 26, 2026 (ARM Title 24, chapter 301). The codes are administered by the Building Codes Program in the Department of Labor and Industry; local building departments issue permits under the adopted codes. Confirm the locally adopted edition with the city or county building department.', 'Montana Building Codes Program (Dept. of Labor and Industry)', 'https://bsd.dli.mt.gov/building-codes-permits/current-codes', '2026-11-24'),
  ('NE', 'Nebraska sets its state building code in statute (Neb. Rev. Stat. §71-6403): the 2018 IBC, IRC, IEBC and UPC. If a local jurisdiction fails to adopt a conforming code, the state code applies there. Confirm the locally adopted edition with the city or county building department.', 'Nebraska Legislature — Neb. Rev. Stat. § 71-6403', 'https://nebraskalegislature.gov/laws/statutes.php?statute=71-6403', '2026-11-24'),
  ('NV', 'The regulations of the State Fire Marshal (NAC 477.281) adopt the 2018 International Fire Code, International Building Code and International Existing Building Code. The 2024 editions of those codes were adopted under Regulation R205-24 and are enforced from January 1, 2026; the State Public Works Division adopts the 2024 IBC for state buildings (NAC 341.045). There is no general statewide building code for private construction, so confirm the locally adopted edition with the city or county building department.', 'Nevada Administrative Code § 477.281', 'https://www.law.cornell.edu/regulations/nevada/NAC-477-281', '2026-11-24'),
  ('NH', 'New Hampshire enforces the State Building Code (RSA 155-A): the 2021 IBC, IRC, IEBC, IPC, IMC and ISPSC, plus the 2020 National Electrical Code, effective July 1, 2024 (House Bill 1059, signed August 2, 2024), with full enforcement from January 1, 2025. The energy code remains the 2018 IECC. The code is reviewed by the Building Code Review Board and applies statewide; local amendments must be submitted to the board for review before enforcement.', 'New Hampshire General Court — HB 1059 (2024)', 'http://gencourt.state.nh.us/BillHistory/SofS_Archives/2024/house/HB1059H.pdf', '2026-11-24'),
  ('NJ', 'New Jersey enforces the Uniform Construction Code (N.J.A.C. 5:23), administered by the Division of Codes and Standards in the Department of Community Affairs. The current code is the 2021 IBC, IRC, IECC, IMC and IFGC (New Jersey editions) plus the 2020 National Electrical Code, effective September 6, 2022. The code is uniform statewide, with no local amendments.', 'New Jersey Dept. of Community Affairs — Uniform Construction Code', 'https://www.nj.gov/dca/codes/codreg/pdf_rule_adoptions/2021_ICode_2020_NEC_adopt.pdf', '2026-11-24'),
  ('NM', 'New Mexico enforces the 2021 New Mexico Commercial Building Code (based on the 2021 IBC) and the 2021 Residential Building Code, effective July 14, 2023 (14.7.2 and 14.7.3 NMAC). The codes are administered by the Construction Industries Division in the Regulation and Licensing Department, which issues permits where no local building department exists. Confirm the locally adopted edition with the city or county building department.', 'New Mexico Construction Industries Division — 14.7.2 NMAC', 'https://www.rld.nm.gov/wp-content/uploads/2024/09/14.7.2-NMCBC-Amendment-6.24.24-TKMR.pdf', '2026-11-24'),
  ('NY', 'New York enforces the 2020 Uniform Fire Prevention and Building Code (based on the 2018 ICC codes), effective May 12, 2020 (19 NYCRR Parts 1220–1227). The code is administered by the Division of Building Standards and Codes in the Department of State and applies statewide. A 2024 update based on the 2024 ICC codes was in final-draft stage in July 2024 and had not been verified as adopted.', 'New York Dept. of State — Division of Building Standards and Codes', 'https://dos.ny.gov/2020-04-nycrr-changes-2020-codes', '2026-11-24'),
  ('NC', 'North Carolina enforces the 2018 North Carolina Codes (based on the 2015 I-Codes), effective January 1, 2019, which remain the codes currently in effect. The codes are set by the Building Code Council and enforced through the Office of the State Fire Marshal in the Department of Insurance. The 2024 codes have been approved, but their effective date was still under review per a State Fire Marshal letter of March 31, 2025.', 'North Carolina Office of State Fire Marshal — Codes', 'https://www.ncosfm.gov/codes/codes-current-and-past', '2026-11-24'),
  ('ND', 'The North Dakota State Building Code is opt-in: a jurisdiction that chooses to enforce a building code must adopt the state code. The code is administered by the Division of Community Services in the Department of Commerce; the 2024 updates (IBC, IRC, IMC, IFGC, IECC and IEBC) were adopted September 11, 2025 and took effect January 1, 2026. Confirm whether the city or county enforces a code and which edition applies.', 'North Dakota Dept. of Commerce — Building Codes', 'https://www.commerce.nd.gov/community-services/building-codes', '2026-11-24'),
  ('OH', 'Ohio enforces the 2024 Ohio Building Code, incorporating the 2021 IBC, IMC, IPC, IFGC, IECC and IEBC, effective March 1, 2024. The code is set by the Board of Building Standards in the Department of Commerce and applies statewide. Building permits are issued by local building departments under the state code.', 'Ohio Board of Building Standards — 2024 Ohio Building Code', 'https://dam.assets.ohio.gov/image/upload/com.ohio.gov/documents/2024%20Ohio%20Building%20Code%20Rules%20Effective%20March%201%2C%202024.pdf', '2026-11-24'),
  ('OK', 'Oklahoma enforces the 2024 IBC, IRC, IFGC, IMC and IPC with Oklahoma amendments, effective September 14, 2026, as the statewide minimum code. The code is set by the Oklahoma Uniform Building Code Commission. Local jurisdictions enforce the state minimum code and issue permits.', 'Oklahoma Uniform Building Code Commission', 'https://oklahoma.gov/cib/news/2026-updated-building-code.html', '2026-11-24'),
  ('OR', 'Oregon enforces the 2022 Oregon Structural Specialty Code (based on the 2021 IBC, IEBC and IFC new-construction provisions), effective October 1, 2022. The code is administered by the Building Codes Division in the Department of Consumer and Business Services and applies statewide. Building permits are issued by local building departments under the state code.', 'Oregon Building Codes Division — Codebook History', 'https://www.oregon.gov/bcd/codes-stand/Pages/codebook-history.aspx', '2026-11-24'),
  ('PA', 'Pennsylvania enforces the Uniform Construction Code (34 Pa. Code §403.21), administered by the Department of Labor and Industry: the 2021 IBC, IRC, IMC, IFGC and IPC, plus the 2020 National Electrical Code, effective January 1, 2026 (published in the Pennsylvania Bulletin, November 8, 2025). The code applies statewide. Building permits are issued by local building departments under the state code.', 'Pennsylvania Uniform Construction Code — 34 Pa. Code § 403.21', 'https://www.pacodeandbulletin.gov/Display/pacode?file=/secure/pacode/data/034/chapter403/s403.21.html&d=', '2026-11-24'),
  ('RI', 'Rhode Island enforces the Rhode Island State Building Code (RISBC-1), which adopts the 2021 IBC with Rhode Island amendments, effective December 1, 2025. The code is set by the Building Code Standards Committee and is the same base code throughout the state. Building permits are issued by local building departments under the state code.', 'Rhode Island Building Code Standards Committee — RISBC-1', 'https://rules.sos.ri.gov/Regulations/part/510-00-00-1', '2026-11-24'),
  ('SC', 'South Carolina enforces the 2021 South Carolina Building, Residential, Fire, Plumbing, Mechanical and Fuel Gas Codes, plus the 2020 National Electrical Code, as the mandatory statewide code, implemented January 1, 2023. The codes are set by the Building Codes Council in the Department of Labor, Licensing and Regulation. Building permits are issued by local building departments under the state code.', 'South Carolina Building Codes Council', 'https://www.llr.sc.gov/BCC/PDFfiles/Building%20Codes%20in%20Effect%20for%20South%20Carolina.pdf', '2026-11-24'),
  ('SD', 'South Dakota has no mandatory statewide building code for private construction; adoption and enforcement are local. State law (SDCL chapter 11-10) sets the standard a local ordinance must follow: a non-residential building ordinance must comply with the 2024 International Building Code, and a residential ordinance must use the 2024 International Residential Code (2026 Senate Bill 129 updated the references from the 2021 editions). Where no local ordinance exists, the 2024 IBC is the design standard for non-residential buildings started after July 1, 2026.', 'South Dakota Legislature — 2026 Senate Bill 129 (SDCL ch. 11-10)', 'https://mylrc.sdlegislature.gov/api/Documents/SessionLaws/304391.pdf', '2026-11-24'),
  ('TN', 'Tennessee enforces statewide minimum building construction safety standards through the State Fire Marshal (Department of Commerce and Insurance, Division of Fire Prevention): the 2021 IBC, IFGC, IMC, IPC, IPMC, IFC, IECC and IEBC, plus the 2018 IRC, in effect since April 17, 2025 (Rule 0780-02-02). Municipalities may become exempt jurisdictions by certifying that they enforce the same codes. Where no local program exists, the State Fire Marshal handles plan review, permits and inspections.', 'Tennessee Secretary of State — Rule 0780-02-02', 'https://publications.tnsosfiles.com/rules/0780/0780-02/0780-02-02.20250417.pdf', '2026-11-24'),
  ('TX', 'Texas has no statewide building code for private construction; cities and counties adopt and enforce their own codes. State law sets the 2012 IBC and IRC as the minimum standard for municipalities, and the Texas Department of Licensing and Regulation requires the 2021 IBC, IRC and related codes for industrialized (modular) housing, effective July 1, 2024. Confirm the locally adopted edition with the city or county building department.', 'Texas Dept. of Licensing and Regulation — Industrialized Housing Codes', 'https://www.tdlr.texas.gov/ihb/codes.htm', '2026-11-24'),
  ('UT', 'Utah enforces the Utah State Construction Code (Utah Code Title 15A): the 2021 IBC, IRC, IPC, IMC, IFGC, IECC and IEBC, plus the 2023 National Electrical Code, effective July 1, 2023 (House Bill 532, 2023). The code is administered by the Division of Occupational and Professional Licensing; local amendments must go through the Legislature. Building permits are issued by local building departments under the state code.', 'Utah Legislature — Utah Code Title 15A, Chapter 2', 'https://le.utah.gov/xcode/Title15A/Chapter2/C15A-2-S103_2025070120250507.rtf', '2026-11-24'),
  ('VT', 'Vermont has no general statewide building or residential code. The 2025 Vermont Fire and Building Safety Code (Department of Public Safety, Division of Fire Safety), effective November 4, 2025, adopts NFPA 101-2021, NFPA 1-2021, IBC-2021 and IEBC-2021 for public buildings only (20 V.S.A. §2730). Most private construction is permitted locally, so confirm requirements with the city or town building department.', 'Vermont Division of Fire Safety — 2025 Fire and Building Safety Code', 'https://firesafety.vermont.gov/sites/firesafety/files/Licensing/Updated%20Web%20Documents/2025%20Vermont%20Fire%20%26%20Building%20Safety%20Code.pdf', '2026-11-24'),
  ('VA', 'Virginia enforces the Virginia Uniform Statewide Building Code (USBC), promulgated by the Board of Housing and Community Development in the Department of Housing and Community Development. The 2021 edition of the USBC is based on the 2021 I-Codes (2021 IBC, IRC, IMC, IPC, IECC and IFGC, plus the 2020 NEC), effective January 18, 2024 and mandatory for all permit applications from January 18, 2025. Building permits are issued by local building departments under the state code.', 'Virginia Administrative Code — 13VAC5-63 (USBC)', 'https://law.lis.virginia.gov/admincode/title13/agency5/chapter63/section10/', '2026-11-24'),
  ('WA', 'Washington enforces the Washington State Building Code, adopted by the State Building Code Council: the 2021 International Building Code (chapter 51-50 WAC) and the 2021 I-Code family, effective July 1, 2023 in all counties and cities. The council reviews and amends the model codes on a three-year cycle. Building permits are issued by local building departments under the state code.', 'Washington State Building Code Council — 2021 IBC', 'https://sbcc.wa.gov/sites/default/files/2023-04/2021%20IBC%20Insert%20Pages%201st%20Printing_0.pdf', '2026-11-24'),
  ('WV', 'West Virginia enforces the State Building Code (87 CSR 4), set by the State Fire Commission: the 2018 IBC, IRC, IPC, IMC, IFGC and IEBC, plus the 2021 NFPA Life Safety Code and the 2020 National Electrical Code, effective August 1, 2022. The code applies statewide. Building permits are issued by local building departments under the state code.', 'West Virginia State Fire Marshal — 87 CSR 4 (State Building Code)', 'https://firemarshal.wv.gov/media/39311/download?inline=&builder=true&fs_ppc_ext=22909&builder_id=8ab1598d5976a2ade0c3145259ffac86&gad_campaignid=23757075564&gad_source=1', '2026-11-24'),
  ('WI', 'Wisconsin enforces the Commercial Building Code (SPS 361–366), administered by the Department of Safety and Professional Services: the 2021 IBC, IECC, IMC, IFGC and IEBC, effective September 1, 2025 and required for all plans submitted from November 1, 2025. One- and two-family dwellings follow the statewide Uniform Dwelling Code (SPS 320–325). Building permits are issued by local building departments under the state codes.', 'Wisconsin Legislature — SPS 361.05 (Commercial Building Code)', 'https://docs.legis.wisconsin.gov/code/admin_code/sps/safety_and_buildings_and_environment/361_366/361/i/05/5?down=1', '2026-11-24'),
  ('WY', 'Wyoming has no single statewide building code; cities and counties adopt and enforce their own codes. The Council on Fire Prevention and Electrical Safety in Buildings sets the minimum fire and life-safety standards of the state (Wyo. Admin. Code 041.0002.1; W.S. 35-9-106): the 2024 IBC, IFC, IMC, IFGC and IEBC, adopted June 28, 2024 and enforced by the State Fire Marshal (Department of Fire Prevention and Electrical Safety). Confirm the locally adopted edition with the city or county building department.', 'ICC — Wyoming Code Adoptions', 'https://www.iccsafe.org/advocacy/adoptions-map/Wyoming/', '2026-11-24')
