-- State-level verified building-permit summaries for the public AHJ directory.
-- Research compiled 2026-11-24 from official state sources only (state .gov
-- sites, state building code councils, official state permit portals, state
-- administrative codes and state statutes); no row where unverifiable —
-- never invented. Mirrors lib/shared/state-summaries.ts (same facts, same
-- access date); the state page renders from the TS data file, this table is
-- the DB mirror so DB and code agree (same pattern as Pass 1 city data).
-- Run once in the Supabase SQL editor. Safe to re-run (ON CONFLICT DO NOTHING).

create table if not exists public.state_summaries (
  state_code text primary key,
  summary text not null,
  source_name text not null,
  source_url text not null,
  verified_at date not null
);

on conflict (state_code) do nothing;
